export {
  controlView,
  descriptionView,
  errorView,
  itemView,
  labelView,
  rootView,
  validityView,
} from "../../../foldkit/ui/field";
export type {
  ControlViewConfig,
  DescriptionViewConfig,
  ErrorViewConfig,
  FieldState,
  FieldStyle,
  ItemViewConfig,
  LabelViewConfig,
  RootViewConfig,
} from "../../../foldkit/ui/field";

export {
  shadcnFieldControlClassName,
  shadcnFieldDescriptionClassName,
  shadcnFieldErrorClassName,
  shadcnFieldItemClassName,
  shadcnFieldLabelClassName,
  shadcnFieldRootClassName,
  shadcnFieldValidityClassName,
} from "./view";

export {
  fieldControlClassName as shadcnFieldControlClassName,
  fieldDescriptionClassName as shadcnFieldDescriptionClassName,
  fieldErrorClassName as shadcnFieldErrorClassName,
  fieldItemClassName as shadcnFieldItemClassName,
  fieldLabelClassName as shadcnFieldLabelClassName,
  fieldRootClassName as shadcnFieldRootClassName,
  fieldValidityClassName as shadcnFieldValidityClassName,
} from "../../../foldkit/ui/field/view";

import { describe, expect, test } from "vitest";

import * as Field from "./index";

describe("shadcn Field registry view", () => {
  test("reuses the Foldkit Field view contract", () => {
    expect(Field.rootView).toBeTypeOf("function");
    expect(Field.labelView).toBeTypeOf("function");
    expect(Field.controlView).toBeTypeOf("function");
    expect(Field.shadcnFieldControlClassName).toContain("aria-[invalid=true]");
  });
});
